            if (result.done) {
              reading = false;
              throwIfNormalizationCancelled(context);
              completed = true;
              closed = true;
              return { __proto__: null, done: true, value: result.value };
            }
            const value = result.value;
            reading = false;
            throwIfNormalizationCancelled(context);
            return { __proto__: null, done: false, value };
