// Token types
const T_AND = 'AND';
const T_OR = 'OR';
const T_NOT = 'NOT';
const T_LPAREN = 'LPAREN';
const T_RPAREN = 'RPAREN';
const T_IDENT = 'IDENT';
const T_EOF = 'EOF';

